def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    def heuristic(current):
        return abs(current[0] - goal[0]) + abs(current[1] - goal[1])
    open_set = []
    heapq.heappush(open_set, (heuristic(start), 0, start))
    came_from = {}
    g_score = {start: 0}
    while open_set:
        current_f, current_g, current_node = heapq.heappop(open_set)
        if current_node == goal:
            path = [current_node]
            while current_node in came_from:
                current_node = came_from[current_node]
                path.append(current_node)
            return path[::-1]
        if current_g != g_score.get(current_node, float('inf')):
            continue
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor = (current_node[0] + dr, current_node[1] + dc)
            if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols:
                if grid[neighbor[0]][neighbor[1]] == '.':
                    tentative_g = current_g + 1
